INSERT IGNORE INTO translations (lang, tkey, value) VALUES
('en','up_title','Update'),
('en','up_available','Version %s is out'),
('en','up_intro','Bandregie does not update itself. That would mean letting the web server write into its own directory, and then any hole that lets someone write a single file once turns into a permanent takeover. A command on the console costs two seconds more and not that price.'),
('en','up_installed','Installed:'),
('en','up_how_git','The script first backs up the database and the files, then fetches the new version:'),
('en','up_how_plesk','This installation runs under Plesk — the directory being served is not a Git working copy, a “git pull” would come to nothing here. Plesk fetches and deploys:'),
('en','up_manual','This installation is not a Git working copy. Copy the new files in, but never overwrite data/ and app/config.php while doing so — and take a backup first.'),
('en','up_cron','If it should run on its own, it belongs in the crontab of the user who owns the working copy:'),
('en','up_check','Check once a day whether there is a new version'),
('en','up_check_hint','Asks GitHub for the version number — without logging in and without any information about this installation. Switched off, Bandregie never reaches out on its own.'),
('en','fl_up_saved','Update setting saved.'),
('en','tax_title','Turnover threshold in view'),
('en','tax_turnover_year','Turnover %d:'),
('en','tax_of','of'),
('en','tax_state_close','You are getting close to the threshold for the current year. Two things follow from that: the exemption ends on 1 January anyway, because this year is already above the previous-year threshold — and if you break the upper threshold as well, it ends immediately, with the very turnover that breaks it.'),
('en','tax_state_next_year','The turnover is above the previous-year threshold. That changes nothing for this year — but the exemption ends by itself on 1 January, no matter how the next year goes. From then on, VAT belongs on every invoice.'),
('en','tax_state_over_this','The threshold for the current year has been passed. The exemption ends with that — talk to your tax adviser before the next invoice goes out.'),
('en','tax_state_over_prev','Last year''s turnover was above the threshold. The exemption therefore no longer applies for this year.'),
('en','tax_counts_hint','Counted is all income of the band except the members'' deposits — those are contributions, not sales. Private entries stay out of it.'),
('en','tax_gbr_hint','The calculation uses the turnover of the band as a whole. That fits if you perform and invoice together — the usual case. If every member writes their own invoices, each one counts for themselves instead, and this figure says nothing about that.'),
('en','tax_no_advice','A calculation aid, not tax advice — and none of it is legally binding. What ends up being declared is the responsibility of the band and its tax adviser, not of this program. The thresholds are in the settings and can be changed.'),
('en','set_tax','Tax figures'),
('en','set_tax_hint','The preset values are the German ones. If the legislator changes the figures — or if you are based elsewhere — enter them here and confirm the date.'),
('en','set_tax_small','We use the small-business rule (Kleinunternehmerregelung, § 19 UStG)'),
('en','set_tax_small_hint','Only then does the treasury keep count and warn you at the threshold.'),
('en','set_tax_prev','Threshold previous year (€)'),
('en','set_tax_gwg','Threshold for low-value assets (GWG, € net)'),
('en','set_tax_gwg_hint','Up to this amount a device is written off in the year of purchase, above it over its useful life.'),
('en','set_tax_checked','Figures last checked on'),
('en','set_tax_source','As of July 2026, Germany: § 19 UStG 25,000 € previous year and 100,000 € current year, § 6 Abs. 2 EStG 800 € net.'),
('en','sys_tax_stale','Tax figures'),
('en','sys_tax_stale_detail','not confirmed for over a year'),
('en','sys_tax_stale_conseq','Check whether the thresholds are still right and confirm the date in the settings.'),
('en','fl_tax_saved','Tax figures saved.'),
('en','help_tax_title','Turnover threshold and the small-business rule (Kleinunternehmerregelung)'),
('en','help_tax_what','Anyone using the small-business rule (Kleinunternehmerregelung, § 19 UStG) shows no VAT on invoices and pays none over. That holds as long as the turnover of the previous year stays below the one threshold and that of the current year below the other. Both figures are in the settings and can be changed.'),
('en','help_tax_band','The calculation uses the turnover of the band as a whole, not per head. As soon as several people perform together and share a fee, they are legally a partnership (GbR) — that needs no registration, it comes about by doing it. For VAT purposes this GbR is the taxable person, so the threshold applies once for everyone together. If instead every member writes their own invoices, each has their own threshold, and the figure in the treasury says nothing about that.'),
('en','help_tax_counts','Fees, merch and sold equipment count as turnover. Members'' deposits do not — those are contributions, not sales. Private entries stay out of it anyway.'),
('en','help_tax_over','The threshold for the current year is a hard ceiling: the very turnover that exceeds it is already taxable. That is why the treasury speaks up from four fifths of the threshold on — not only once it is too late. Anyone who loses the rule taxes performances at the reduced rate and merch at the full one; what that means for you is better sorted out beforehand than afterwards.'),
('en','help_tax_next_year','The more likely case is the quieter one: if the turnover stays between the two thresholds, nothing changes this year — but the exemption ends on 1 January of the following year, automatically and without notice. How high the turnover in the new year turns out no longer matters then. Anyone who only learns of it from the tax assessment has spent a year writing invoices without VAT that they now have to pay tax on retroactively.'),
('en','help_tax_gwg','A second threshold applies to devices: up to this net amount a purchase is written off in the year of acquisition, above it spread over the useful life. For loudspeakers the official table (AfA-Tabelle) assumes seven years, for complete PA systems nine.'),
('en','help_tax_sources','Where the figures come from'),
('en','help_tax_checked','Last checked on %s. Advice sites often lag behind here — the statutes themselves are the reliable source.'),
('en','help_tax_src_ustg','— the turnover thresholds of the small-business rule'),
('en','help_tax_src_estg','— the threshold for low-value assets'),
('en','help_tax_src_afa','— the useful life for everything above it'),
('en','help_tax_offset_title','What cancels itself out'),
('en','help_tax_offset_intro','The treasury adds up what has been entered. Some of it looks like income or an expense there and is something else for tax purposes — read straight, it gives you a wrong figure with a clear conscience.'),
('en','help_tax_offset_deposit','A deposit is money in for the band and money out for the member. It is a contribution, not a sale, and therefore does not count towards turnover.'),
('en','help_tax_offset_payout','A payout sits in the books as an expense, but for a GbR it is not a business expense: it distributes a profit that has already arisen. Setting it against the profit deducts that profit twice.'),
('en','help_tax_offset_private','What a member has paid privately is that member''s expense, not the band''s. Such entries therefore stay out of it — for the member themselves they may well count.'),
('en','help_tax_offset_gwg','A device above the value threshold leaves the treasury in one amount, but reduces the profit spread over its useful life. The cash book shows one year, for tax purposes it is several.'),
('en','help_tax_levels','Tax relief exists on two levels: some things lower what the band has earned — others lower what an individual member declares. Your own instrument, the drive to rehearsal, the share of the profit: that belongs in the personal tax return and not in the band''s figures. Throwing both together gives a total that is right for neither side.'),
('en','tax_comm_title','Share of trade'),
('en','tax_comm_intro','Playing is artistic, selling merch is trade. In a partnership even a small share of trade makes all income commercial — including the income from performances. It is tolerated only below both thresholds.'),
('en','tax_comm_of','of'),
('en','tax_comm_state_close','The share of trade is approaching the threshold.'),
('en','tax_comm_state_over','The share of trade is above the threshold. With that, all of the band''s income counts as commercial, including the income from performances — with trade tax (Gewerbesteuer) above the allowance. This belongs on the table with your tax adviser.'),
('en','set_tax_comm_share','Share of trade at most (%)'),
('en','set_tax_comm_abs','Trade turnover at most (€)'),
('en','set_tax_comm_hint','Both must hold, otherwise all income counts as commercial. In Germany 3 % of net turnover and 24,500 € a year, from the case law on § 15 Abs. 3 Nr. 1 EStG.'),
('en','help_est_title','Income tax: who pays what'),
('en','help_est_who','The band itself pays no income tax. Its profit is determined once and split among the members — at the tax office this is called a separate and uniform assessment (gesonderte und einheitliche Feststellung). Each member declares their share in their own tax return. That is why both are needed: clean figures for the band and clarity about what of them lands with the individual.'),
('en','help_est_euer','For a band the profit is as a rule determined by a cash-basis statement (Einnahmen-Überschuss-Rechnung, EÜR): taken in minus paid out, in the year of payment. That is exactly what a cash book is — kept cleanly, the work is essentially done.'),
('en','help_est_merch','Playing is an artistic activity, selling T-shirts is trade. In a partnership a small share of trade is enough for all income to count as commercial — including the income from performances. It is tolerated only below both thresholds at once: under three percent of net turnover and under 24,500 € a year. Three percent is not much: if you take in 20,000 € in fees, you may sell around 600 € of merch. Above that the whole band becomes a trade, with trade tax (Gewerbesteuer) above the allowance of 24,500 €.'),
('en','help_est_hobby','And the reverse case: anyone who makes no profit for years and does not aim for one may count as a hobby (Liebhaberei) to the tax office. The band is then not a business for tax purposes — which means the losses are worth nothing either.'),
('en','help_est_src_est15','— when all income becomes commercial'),
('en','help_est_src_est18','— the artistic activity'),
('en','help_est_src_bfh','— the de-minimis threshold from case law'),
('en','help_est_own_title','What counts for the individual musician'),
('en','help_est_own_taxed','What is taxed is the share of the profit — even if nothing has been paid out. If the band is saving up for a PA, nobody has seen any money and yet everyone declares their share. That regularly comes as a surprise.'),
('en','help_est_own_costs','Against that stands what does not appear in the band''s figures at all: your own instrument with strings and accessories, journeys to rehearsals and gigs, sheet music and specialist literature, a home office under narrow conditions, contributions to the artists'' social insurance fund (Künstlersozialkasse). That belongs in the personal tax return.'),
('en','help_est_own_km','Journeys in your own car for the band are business trips: 30 cents per kilometre driven. Not to be confused with the commuter allowance (Pendlerpauschale), which rises to 38 cents in 2026 — that applies to the way to a fixed place of work, and anyone playing somewhere else every time does not have one.'),
('en','help_est_own_home','For working at home there are 6 euros a day, at most 1,260 euros a year — that corresponds to 210 days.'),
('en','help_est_own_ksk','The artists'' social insurance fund (Künstlersozialkasse) insures those who work artistically, self-employed and for a living. Below 3,900 euros of annual income no insurance obligation is established. The other way round: if the band itself pays guest musicians, it may owe the artists'' social security levy (Künstlersozialabgabe) — 4.9 percent in 2026, with a de-minimis threshold of 1,000 euros a year.'),
('en','help_est_src_ksk','— who is insured and from when'),
('en','fl_file_sealed','This file is stored encrypted and cannot be opened with the key that is entered.'),
('en','set_crypt','Encryption of data at rest'),
('en','set_crypt_on','Switched on: backups and attachments are stored encrypted.'),
('en','set_crypt_off','Switched off: backups and attachments lie there in plain text.'),
('en','set_crypt_scope','Encrypted are the backups and the file attachments on disk. Not encrypted is the running database — the server has to be able to compute and sort in there — and not the images under /uploads, which the web server delivers directly.'),
('en','set_crypt_test','Effectiveness checked: %s.'),
('en','set_crypt_plain_files','%d attachments date from before that and are still lying open.'),
('en','set_crypt_seal_now','Encrypt them now'),
('en','set_crypt_files_done','All attachments are encrypted.'),
('en','set_crypt_how','Generate a key and enter it as “data_key” in app/config.php:'),
('en','set_crypt_lost','Keep this key like the database password — and not in the same backup. Without it, no encrypted backup can be opened again.'),
('en','set_crypt_law','Art. 32 GDPR (DSGVO) requires measures that reflect the state of the art and names encryption explicitly; letter d also requires its effectiveness to be tested regularly. That is exactly what the line above does: seal, open again, and check whether a change is noticed.'),
('en','sys_crypt_off','no key entered'),
('en','sys_crypt_off_hint','Backups and attachments lie there in plain text. Anyone who gets hold of the backup — on the NAS, at the FTP target, in the cloud — reads the treasury along with it. Generate a key: php app/backup.php key'),
('en','sys_crypt_broken','Encryption is switched on, but the check fails. Until that is sorted out, the backups cannot be relied on.'),
('en','sys_webstat','Visitor statistics'),
('en','sys_webstat_open','publicly readable'),
('en','sys_webstat_closed','protected'),
('en','sys_webstat_unknown','cannot be checked'),
('en','sys_webstat_hint','Under /plesk-stat lie the AWStats reports of this domain, and they contain the IP addresses of your visitors — open to anyone who knows the address. In Plesk, under “Websites & Domains → Hosting and DNS → Web Statistics”, tick “Accessible via password-protected directory”.'),
('en','sys_crypt_files','Attachments encrypted'),
('en','sys_crypt_files_hint','Encrypt them afterwards in the settings under “Encryption of data at rest”.'),
('en','fl_crypt_no_key','No key has been entered.'),
('en','fl_crypt_sealed','%d attachments encrypted.'),
('en','fl_crypt_sealed_some','%d attachments encrypted, %d failed — details in the error log.'),
('nl','up_title','Bijwerken'),
('nl','up_available','Versie %s is er'),
('nl','up_intro','Bandregie werkt zichzelf niet bij. Daarvoor zou de webserver in zijn eigen map moeten mogen schrijven, en dan wordt elk lek waarmee iemand één keer een bestand kan schrijven een blijvende overname. Een commando op de console kost twee seconden meer en die prijs niet.'),
('nl','up_installed','Geïnstalleerd:'),
('nl','up_how_git','Het script maakt eerst een back-up van database en bestanden en haalt dan de nieuwe versie op:'),
('nl','up_how_plesk','Deze installatie draait onder Plesk — de uitgeleverde map is geen Git-werkkopie, een „git pull” doet hier niets. Plesk haalt op en zet uit:'),
('nl','up_manual','Deze installatie is geen Git-werkkopie. Nieuwe bestanden erin zetten, maar data/ en app/config.php daarbij nooit overschrijven — en vooraf een back-up maken.'),
('nl','up_cron','Moet het vanzelf lopen, dan hoort het in de crontab van de gebruiker die de werkkopie bezit:'),
('nl','up_check','Eén keer per dag kijken of er een nieuwe versie is'),
('nl','up_check_hint','Vraagt bij GitHub het versienummer op — zonder aanmelding en zonder gegevens over deze installatie. Uitgeschakeld neemt Bandregie nooit uit zichzelf contact met buiten op.'),
('nl','fl_up_saved','Instelling voor bijwerken opgeslagen.'),
('nl','tax_title','Omzetgrens in beeld'),
('nl','tax_turnover_year','Omzet %d:'),
('nl','tax_of','van'),
('nl','tax_state_close','Jullie komen dicht bij de grens voor het lopende jaar. Daarmee staan twee dingen te gebeuren: de vrijstelling eindigt sowieso op 1 januari, omdat dit jaar al boven de grens van het voorgaande jaar ligt — en als jullie ook de bovengrens doorbreken, eindigt ze meteen, met de omzet die haar doorbreekt.'),
('nl','tax_state_next_year','De omzet ligt boven de grens van het voorgaande jaar. Voor dit jaar verandert dat niets — maar de vrijstelling eindigt vanzelf op 1 januari, ongeacht hoe het volgende jaar loopt. Vanaf dan hoort er btw op elke factuur.'),
('nl','tax_state_over_this','De grens voor het lopende jaar is overschreden. Daarmee eindigt de vrijstelling — overleg met jullie belastingadviseur voordat de volgende factuur de deur uitgaat.'),
('nl','tax_state_over_prev','De omzet van vorig jaar lag boven de grens. Daarmee geldt de vrijstelling voor dit jaar niet meer.'),
('nl','tax_counts_hint','Meegeteld worden alle inkomsten van de band behalve de stortingen van de leden — dat zijn bijdragen en geen verkoop. Privéboekingen blijven erbuiten.'),
('nl','tax_gbr_hint','Er wordt gerekend met de omzet van de band als geheel. Dat klopt als jullie samen optreden en afrekenen — het normale geval. Schrijft elk lid eigen facturen, dan telt in plaats daarvan ieder voor zich, en dit getal zegt daar niets over.'),
('nl','tax_no_advice','Een rekenhulp, geen belastingadvies — en niets hiervan is juridisch bindend. Wat uiteindelijk wordt aangegeven, is de verantwoordelijkheid van de band en haar belastingadviseur, niet van dit programma. De grenzen staan in de instellingen en zijn aan te passen.'),
('nl','set_tax','Fiscale waarden'),
('nl','set_tax_hint','Vooringesteld is de Duitse stand. Verandert de wetgever de cijfers — of zitten jullie ergens anders — vul ze hier in en bevestig de datum.'),
('nl','set_tax_small','Wij gebruiken de kleineondernemersregeling (Kleinunternehmerregelung, § 19 UStG)'),
('nl','set_tax_small_hint','Pas dan telt de kas mee en waarschuwt ze bij de grens.'),
('nl','set_tax_prev','Grens voorgaand jaar (€)'),
('nl','set_tax_gwg','Grens geringe bedrijfsmiddelen (GWG, € netto)'),
('nl','set_tax_gwg_hint','Tot dit bedrag is een apparaat in het jaar van aankoop afgeschreven, daarboven over de gebruiksduur.'),
('nl','set_tax_checked','Waarden laatst gecontroleerd op'),
('nl','set_tax_source','Stand juli 2026, Duitsland: § 19 UStG 25.000 € voorgaand jaar en 100.000 € lopend jaar, § 6 Abs. 2 EStG 800 € netto.'),
('nl','sys_tax_stale','Fiscale waarden'),
('nl','sys_tax_stale_detail','al meer dan een jaar niet bevestigd'),
('nl','sys_tax_stale_conseq','Controleer of de grenzen nog kloppen en bevestig de datum in de instellingen.'),
('nl','fl_tax_saved','Fiscale waarden opgeslagen.'),
('nl','help_tax_title','Omzetgrens en de kleineondernemersregeling (Kleinunternehmerregelung)'),
('nl','help_tax_what','Wie de kleineondernemersregeling (Kleinunternehmerregelung, § 19 UStG) gebruikt, zet geen btw op de factuur en draagt er ook geen af. Dat geldt zolang de omzet in het voorgaande jaar onder de ene en in het lopende jaar onder de andere grens blijft. Beide getallen staan in de instellingen en zijn aan te passen.'),
('nl','help_tax_band','Er wordt gerekend met de omzet van de band als geheel, niet per hoofd. Zodra meerderen samen optreden en een gage delen, zijn ze juridisch een maatschap (GbR) — daarvoor is geen inschrijving nodig, dat ontstaat door het doen. Voor de omzetbelasting is deze GbR de belastingplichtige, de grens geldt dus één keer voor allen samen. Schrijft daarentegen elk lid eigen facturen, dan heeft ieder zijn eigen grens, en het getal in de kas zegt daar niets over.'),
('nl','help_tax_counts','Als omzet tellen gages, merch en verkochte apparatuur. Stortingen van leden tellen niet — dat zijn bijdragen en geen verkoop. Privéboekingen blijven sowieso buiten beschouwing.'),
('nl','help_tax_over','De grens voor het lopende jaar is een harde bovengrens: al de omzet waarmee ze wordt overschreden is belastingplichtig. Daarom meldt de kas zich vanaf vier vijfde van de grens — niet pas als het te laat is. Wie de regeling verliest, belast optredens tegen het verlaagde en merch tegen het volle tarief; wat dat voor jullie betekent, zoek je beter vooraf uit dan achteraf.'),
('nl','help_tax_next_year','Het waarschijnlijker geval is het stillere: blijft de omzet tussen de twee grenzen, dan verandert er dit jaar niets — maar de vrijstelling eindigt op 1 januari van het volgende jaar, automatisch en zonder bericht. Hoe hoog de omzet in het nieuwe jaar wordt, doet dan niet meer ter zake. Wie dat pas bij de aanslag te horen krijgt, heeft een jaar lang facturen zonder btw geschreven waarover alsnog moet worden afgedragen.'),
('nl','help_tax_gwg','Voor apparatuur geldt een tweede grens: tot dit bedrag netto is een aankoop in het jaar van aanschaf afgeschreven, daarboven verdeeld over de gebruiksduur. Voor luidsprekers rekent de officiële tabel (AfA-Tabelle) met zeven jaar, voor complete geluidsinstallaties met negen.'),
('nl','help_tax_sources','Waar de cijfers vandaan komen'),
('nl','help_tax_checked','Laatst gecontroleerd op %s. Adviessites lopen hier vaak achter — de wetteksten zijn de betrouwbare bron.'),
('nl','help_tax_src_ustg','— de omzetgrenzen van de kleineondernemersregeling'),
('nl','help_tax_src_estg','— de grens voor geringe bedrijfsmiddelen'),
('nl','help_tax_src_afa','— de gebruiksduur voor alles daarboven'),
('nl','help_tax_offset_title','Wat elkaar opheft'),
('nl','help_tax_offset_intro','De kas telt op wat is geboekt. Sommige dingen zien er daar uit als inkomst of uitgave en zijn fiscaal iets anders — wie het rechttoe rechtaan leest, komt met een gerust hart op een verkeerd getal uit.'),
('nl','help_tax_offset_deposit','Een storting is geld binnen voor de band en geld buiten voor het lid. Het is een bijdrage en geen verkoop en telt daarom niet mee voor de omzet.'),
('nl','help_tax_offset_payout','Een uitkering staat als uitgave in de boeken, maar is voor een GbR geen bedrijfskost: ze verdeelt een winst die al is ontstaan. Wie haar tegen de winst wegstreept, trekt die twee keer af.'),
('nl','help_tax_offset_private','Wat een lid privé heeft betaald, is diens uitgave en niet die van de band. Zulke boekingen blijven daarom buiten beschouwing — bij het lid zelf kunnen ze wel degelijk meetellen.'),
('nl','help_tax_offset_gwg','Een apparaat boven de waardegrens verlaat de kas in één bedrag, maar drukt de winst verdeeld over de gebruiksduur. In het kasboek staat één jaar, fiscaal zijn het er meerdere.'),
('nl','help_tax_levels','Belastingverlagend werkt op twee niveaus: sommige dingen verlagen wat de band heeft verdiend — andere verlagen wat een afzonderlijk lid aangeeft. Het eigen instrument, de rit naar de repetitie, het winstaandeel: dat hoort in de persoonlijke aangifte en niet in de cijfers van de band. Wie beide op één hoop gooit, krijgt een som die voor geen van beide kanten klopt.'),
('nl','tax_comm_title','Aandeel handel'),
('nl','tax_comm_intro','Spelen is artistiek, merch verkopen is handel. Bij een personenvennootschap maakt al een klein handelsaandeel alle inkomsten commercieel — ook die uit de optredens. Het wordt alleen onder beide grenzen gedoogd.'),
('nl','tax_comm_of','van'),
('nl','tax_comm_state_close','Het handelsaandeel nadert de grens.'),
('nl','tax_comm_state_over','Het handelsaandeel ligt boven de grens. Daarmee gelden alle inkomsten van de band als commercieel, ook die uit de optredens — met bedrijfsbelasting (Gewerbesteuer) boven de vrijstelling. Dit hoort met de belastingadviseur besproken te worden.'),
('nl','set_tax_comm_share','Handelsaandeel hoogstens (%)'),
('nl','set_tax_comm_abs','Handelsomzet hoogstens (€)'),
('nl','set_tax_comm_hint','Beide moeten gelden, anders gelden alle inkomsten als commercieel. In Duitsland 3 % van de netto-omzet en 24.500 € per jaar, uit de rechtspraak bij § 15 Abs. 3 Nr. 1 EStG.'),
('nl','help_est_title','Inkomstenbelasting: wie betaalt wat'),
('nl','help_est_who','De band zelf betaalt geen inkomstenbelasting. De winst wordt één keer vastgesteld en over de leden verdeeld — bij de belastingdienst heet dat gesonderte und einheitliche Feststellung. Elk lid geeft zijn aandeel in de eigen aangifte op. Daarom is beide nodig: zuivere cijfers voor de band en duidelijkheid over wat daarvan bij het individu terechtkomt.'),
('nl','help_est_euer','De winst wordt bij een band in de regel bepaald als een kasstelseloverzicht (Einnahmen-Überschuss-Rechnung, EÜR): ontvangen min uitgegeven, in het jaar van betaling. Precies dat is een kasboek — netjes bijgehouden is het werk in wezen gedaan.'),
('nl','help_est_merch','Spelen is een artistieke bezigheid, T-shirts verkopen is handel. Bij een personenvennootschap volstaat een klein handelsaandeel om alle inkomsten als commercieel te laten gelden — ook die uit de optredens. Het wordt alleen onder beide grenzen tegelijk gedoogd: onder drie procent van de netto-omzet en onder 24.500 € per jaar. Drie procent is weinig: wie 20.000 € aan gages ontvangt, mag voor ongeveer 600 € merch verkopen. Daarboven wordt de hele band een onderneming, met bedrijfsbelasting (Gewerbesteuer) boven de vrijstelling van 24.500 €.'),
('nl','help_est_hobby','En het omgekeerde geval: wie jarenlang geen winst maakt en die ook niet nastreeft, geldt bij de belastingdienst mogelijk als liefhebberij (Liebhaberei). Dan is de band fiscaal geen onderneming — en zijn de verliezen dus evenmin iets waard.'),
('nl','help_est_src_est15','— wanneer alle inkomsten commercieel worden'),
('nl','help_est_src_est18','— de artistieke bezigheid'),
('nl','help_est_src_bfh','— de bagatelgrens uit de rechtspraak'),
('nl','help_est_own_title','Wat bij de individuele muzikant telt'),
('nl','help_est_own_taxed','Belast wordt het aandeel in de winst — ook als er niets is uitgekeerd. Spaart de band voor een PA, dan heeft niemand geld gezien en toch geeft ieder zijn aandeel aan. Dat verrast telkens weer.'),
('nl','help_est_own_costs','Daartegenover staat wat in de cijfers van de band helemaal niet voorkomt: het eigen instrument met snaren en toebehoren, ritten naar repetities en optredens, bladmuziek en vakliteratuur, een werkkamer onder strikte voorwaarden, premies aan de sociale kas voor kunstenaars (Künstlersozialkasse). Dat hoort in de persoonlijke aangifte.'),
('nl','help_est_own_km','Ritten met de eigen auto voor de band zijn zakelijke ritten: 30 cent per gereden kilometer. Niet te verwarren met de forfaitaire reisaftrek (Pendlerpauschale), die in 2026 naar 38 cent gaat — die geldt voor de weg naar een vaste werkplek, en die heeft niet wie elke keer ergens anders speelt.'),
('nl','help_est_own_home','Voor het werken thuis geldt 6 euro per dag, hoogstens 1.260 euro per jaar — dat komt neer op 210 dagen.'),
('nl','help_est_own_ksk','De Künstlersozialkasse verzekert wie artistiek, zelfstandig en beroepsmatig werkt. Onder 3.900 euro jaarinkomen wordt geen verzekeringsplicht vastgesteld. Omgekeerd geldt: betaalt de band zelf gastmuzikanten, dan kan ze de Künstlersozialabgabe verschuldigd zijn — 4,9 procent in 2026, met een bagatelgrens van 1.000 euro per jaar.'),
('nl','help_est_src_ksk','— wie verzekerd is en vanaf wanneer'),
('nl','fl_file_sealed','Dit bestand is versleuteld opgeslagen en is met de ingevoerde sleutel niet te openen.'),
('nl','set_crypt','Versleuteling van rustende gegevens'),
('nl','set_crypt_on','Ingeschakeld: back-ups en bijlagen liggen versleuteld.'),
('nl','set_crypt_off','Uitgeschakeld: back-ups en bijlagen liggen in leesbare vorm.'),
('nl','set_crypt_scope','Versleuteld zijn de back-ups en de bijlagen op de schijf. Niet versleuteld is de draaiende database — daar moet de server kunnen rekenen en sorteren — en ook niet de afbeeldingen onder /uploads, die de webserver rechtstreeks uitlevert.'),
('nl','set_crypt_test','Werking gecontroleerd: %s.'),
('nl','set_crypt_plain_files','%d bijlagen stammen uit de tijd daarvoor en liggen nog open.'),
('nl','set_crypt_seal_now','Nu alsnog versleutelen'),
('nl','set_crypt_files_done','Alle bijlagen zijn versleuteld.'),
('nl','set_crypt_how','Een sleutel genereren en als „data_key” in app/config.php invullen:'),
('nl','set_crypt_lost','Bewaar deze sleutel zoals het databasewachtwoord — en niet in dezelfde back-up. Zonder hem is geen versleutelde back-up meer te openen.'),
('nl','set_crypt_law','Art. 32 AVG (DSGVO) verlangt maatregelen die aansluiten bij de stand van de techniek en noemt versleuteling uitdrukkelijk; letter d verlangt bovendien de werking ervan regelmatig te toetsen. Precies dat doet de regel hierboven: verzegelen, weer openen, en kijken of een verandering opvalt.'),
('nl','sys_crypt_off','geen sleutel ingevuld'),
('nl','sys_crypt_off_hint','Back-ups en bijlagen liggen in leesbare vorm. Wie de back-up in handen krijgt — op de NAS, bij het FTP-doel, in de cloud — leest de kas mee. Sleutel genereren: php app/backup.php key'),
('nl','sys_crypt_broken','De versleuteling staat aan, maar de controle mislukt. Tot dat is uitgezocht, is op de back-ups geen staat te maken.'),
('nl','sys_webstat','Bezoekersstatistiek'),
('nl','sys_webstat_open','openbaar leesbaar'),
('nl','sys_webstat_closed','beschermd'),
('nl','sys_webstat_unknown','niet te controleren'),
('nl','sys_webstat_hint','Onder /plesk-stat staan de AWStats-rapporten van dit domein, en daarin staan de IP-adressen van jullie bezoekers — open voor iedereen die het adres kent. Zet in Plesk onder „Websites & domeinen → Hosting en DNS → Webstatistieken” het vinkje „Toegang via met wachtwoord beveiligde map”.'),
('nl','sys_crypt_files','Bijlagen versleuteld'),
('nl','sys_crypt_files_hint','In de instellingen onder „Versleuteling van rustende gegevens” alsnog versleutelen.'),
('nl','fl_crypt_no_key','Er is geen sleutel ingevuld.'),
('nl','fl_crypt_sealed','%d bijlagen versleuteld.'),
('nl','fl_crypt_sealed_some','%d bijlagen versleuteld, %d mislukt — details in het foutenlogboek.'),
('fr','up_title','Mise à jour'),
('fr','up_available','La version %s est disponible'),
('fr','up_intro','Bandregie ne se met pas à jour tout seul. Il faudrait pour cela que le serveur web ait le droit d''écrire dans son propre répertoire, et alors la moindre faille permettant d''écrire un fichier une seule fois deviendrait une prise de contrôle durable. Une commande en console coûte deux secondes de plus et pas ce prix-là.'),
('fr','up_installed','Installée :'),
('fr','up_how_git','Le script sauvegarde d''abord la base de données et les fichiers, puis récupère la nouvelle version :'),
('fr','up_how_plesk','Cette installation tourne sous Plesk — le répertoire servi n''est pas une copie de travail Git, un « git pull » n''aurait aucun effet ici. Plesk récupère et déploie :'),
('fr','up_manual','Cette installation n''est pas une copie de travail Git. Copiez les nouveaux fichiers, mais n''écrasez jamais data/ ni app/config.php au passage — et faites une sauvegarde avant.'),
('fr','up_cron','Pour que cela se fasse tout seul, la ligne va dans la crontab de l''utilisateur propriétaire de la copie de travail :'),
('fr','up_check','Vérifier une fois par jour s''il existe une nouvelle version'),
('fr','up_check_hint','Demande le numéro de version à GitHub — sans identification et sans aucune donnée sur cette installation. Désactivé, Bandregie ne s''adresse jamais de lui-même à l''extérieur.'),
('fr','fl_up_saved','Réglage de mise à jour enregistré.'),
('fr','tax_title','Le seuil de chiffre d''affaires en vue'),
('fr','tax_turnover_year','Chiffre d''affaires %d :'),
('fr','tax_of','sur'),
('fr','tax_state_close','Vous approchez du seuil de l''année en cours. Deux choses en découlent : l''exonération prend fin au 1er janvier de toute façon, parce que cette année dépasse déjà le seuil de l''année précédente — et si vous franchissez aussi le seuil supérieur, elle prend fin immédiatement, avec le chiffre d''affaires qui le franchit.'),
('fr','tax_state_next_year','Le chiffre d''affaires dépasse le seuil de l''année précédente. Cela ne change rien pour cette année — mais l''exonération prend fin d''elle-même au 1er janvier, quelle que soit l''allure de l''année suivante. À partir de là, la TVA figure sur chaque facture.'),
('fr','tax_state_over_this','Le seuil de l''année en cours est dépassé. L''exonération prend donc fin — parlez-en à votre cabinet comptable avant que la prochaine facture ne parte.'),
('fr','tax_state_over_prev','Le chiffre d''affaires de l''année précédente dépassait le seuil. L''exonération ne s''applique donc plus cette année.'),
('fr','tax_counts_hint','Sont comptées toutes les recettes du groupe sauf les versements des membres — ce sont des contributions, pas des ventes. Les écritures privées restent en dehors.'),
('fr','tax_gbr_hint','Le calcul porte sur le chiffre d''affaires du groupe dans son ensemble. Cela convient si vous jouez et facturez ensemble — le cas courant. Si chaque membre établit ses propres factures, chacun compte pour soi, et ce chiffre n''en dit rien.'),
('fr','tax_no_advice','Une aide au calcul, pas un conseil fiscal — et rien de tout cela n''a de valeur juridique. Ce qui est finalement déclaré relève de la responsabilité du groupe et de son cabinet comptable, pas de ce programme. Les seuils sont dans les réglages et peuvent être modifiés.'),
('fr','set_tax','Valeurs fiscales'),
('fr','set_tax_hint','Les valeurs par défaut sont celles de l''Allemagne. Si le législateur modifie les chiffres — ou si vous êtes ailleurs — saisissez-les ici et confirmez la date.'),
('fr','set_tax_small','Nous relevons du régime des petites entreprises (Kleinunternehmerregelung, § 19 UStG)'),
('fr','set_tax_small_hint','Ce n''est qu''ainsi que la caisse tient le compte et vous prévient à l''approche du seuil.'),
('fr','set_tax_prev','Seuil année précédente (€)'),
('fr','set_tax_gwg','Seuil des biens de faible valeur (GWG, € HT)'),
('fr','set_tax_gwg_hint','Jusqu''à ce montant, un appareil est amorti l''année de l''achat, au-delà sur sa durée d''utilisation.'),
('fr','set_tax_checked','Valeurs vérifiées le'),
('fr','set_tax_source','Situation en juillet 2026, Allemagne : § 19 UStG 25 000 € année précédente et 100 000 € année en cours, § 6 Abs. 2 EStG 800 € HT.'),
('fr','sys_tax_stale','Valeurs fiscales'),
('fr','sys_tax_stale_detail','non confirmées depuis plus d''un an'),
('fr','sys_tax_stale_conseq','Vérifiez que les seuils sont toujours exacts et confirmez la date dans les réglages.'),
('fr','fl_tax_saved','Valeurs fiscales enregistrées.'),
('fr','help_tax_title','Seuil de chiffre d''affaires et régime des petites entreprises (Kleinunternehmerregelung)'),
('fr','help_tax_what','Qui relève du régime des petites entreprises (Kleinunternehmerregelung, § 19 UStG) ne fait pas apparaître de TVA sur ses factures et n''en reverse pas. Cela vaut tant que le chiffre d''affaires de l''année précédente reste sous l''un des seuils et celui de l''année en cours sous l''autre. Les deux chiffres sont dans les réglages et peuvent être modifiés.'),
('fr','help_tax_band','Le calcul porte sur le chiffre d''affaires du groupe dans son ensemble, pas par tête. Dès que plusieurs personnes jouent ensemble et se partagent un cachet, elles forment juridiquement une société de droit civil (GbR) — cela ne demande aucune inscription, elle naît du fait même. Pour la TVA, c''est cette GbR qui est l''assujetti, le seuil vaut donc une seule fois pour tous. Si en revanche chaque membre établit ses propres factures, chacun a son propre seuil, et le chiffre de la caisse n''en dit rien.'),
('fr','help_tax_counts','Comptent comme chiffre d''affaires les cachets, le merch et le matériel revendu. Les versements des membres ne comptent pas — ce sont des contributions, pas des ventes. Les écritures privées restent de toute façon en dehors.'),
('fr','help_tax_over','Le seuil de l''année en cours est un plafond dur : le chiffre d''affaires qui le dépasse est déjà lui-même imposable. C''est pourquoi la caisse se manifeste à partir des quatre cinquièmes du seuil — et pas seulement quand il est trop tard. Qui perd le régime taxe les concerts au taux réduit et le merch au taux plein ; ce que cela signifie pour vous, mieux vaut le clarifier avant qu''après.'),
('fr','help_tax_next_year','Le cas le plus probable est le plus discret : si le chiffre d''affaires reste entre les deux seuils, rien ne change cette année — mais l''exonération prend fin au 1er janvier de l''année suivante, automatiquement et sans notification. Le niveau du chiffre d''affaires de la nouvelle année n''y change alors plus rien. Qui ne l''apprend qu''à l''avis d''imposition a passé une année à écrire des factures sans TVA qu''il doit régulariser.'),
('fr','help_tax_gwg','Un second seuil s''applique aux appareils : jusqu''à ce montant hors taxes, un achat est amorti l''année de l''acquisition, au-delà il se répartit sur la durée d''utilisation. Pour les enceintes, la table officielle (AfA-Tabelle) retient sept ans, pour une sonorisation complète neuf.'),
('fr','help_tax_sources','D''où viennent les chiffres'),
('fr','help_tax_checked','Dernière vérification le %s. Les sites de conseils sont souvent en retard ici — les textes de loi sont la source fiable.'),
('fr','help_tax_src_ustg','— les seuils de chiffre d''affaires du régime des petites entreprises'),
('fr','help_tax_src_estg','— le seuil des biens de faible valeur'),
('fr','help_tax_src_afa','— la durée d''utilisation pour tout ce qui est au-dessus'),
('fr','help_tax_offset_title','Ce qui s''annule'),
('fr','help_tax_offset_intro','La caisse additionne ce qui a été saisi. Certaines lignes y ressemblent à une recette ou à une dépense et sont fiscalement autre chose — à les lire au premier degré, on arrive en toute bonne conscience à un chiffre faux.'),
('fr','help_tax_offset_deposit','Un versement, c''est de l''argent qui entre pour le groupe et qui sort pour le membre. C''est une contribution, pas une vente, et cela ne compte donc pas dans le chiffre d''affaires.'),
('fr','help_tax_offset_payout','Une distribution figure au livre comme une dépense, mais pour une GbR ce n''est pas une charge d''exploitation : elle répartit un bénéfice déjà réalisé. La déduire du bénéfice revient à le retrancher deux fois.'),
('fr','help_tax_offset_private','Ce qu''un membre a payé à titre privé est sa dépense, pas celle du groupe. Ces écritures restent donc en dehors — chez le membre lui-même, elles peuvent très bien compter.'),
('fr','help_tax_offset_gwg','Un appareil au-dessus du seuil de valeur quitte la caisse en une seule fois, mais réduit le bénéfice réparti sur sa durée d''utilisation. Le livre de caisse affiche une année, fiscalement il y en a plusieurs.'),
('fr','help_tax_levels','L''allègement fiscal joue à deux niveaux : certaines choses réduisent ce que le groupe a gagné — d''autres réduisent ce qu''un membre déclare pour lui-même. Son propre instrument, le trajet jusqu''à la répétition, la part de bénéfice : cela va dans la déclaration personnelle et pas dans les chiffres du groupe. Mélanger les deux donne un total qui n''est juste pour aucun des deux côtés.'),
('fr','tax_comm_title','Part commerciale'),
('fr','tax_comm_intro','Jouer relève de l''art, vendre du merch relève du commerce. Dans une société de personnes, une petite part commerciale suffit à rendre l''ensemble des revenus commerciaux — y compris ceux des concerts. Cela n''est toléré qu''en dessous des deux seuils.'),
('fr','tax_comm_of','sur'),
('fr','tax_comm_state_close','La part commerciale approche du seuil.'),
('fr','tax_comm_state_over','La part commerciale dépasse le seuil. Tous les revenus du groupe sont dès lors considérés comme commerciaux, y compris ceux des concerts — avec la taxe professionnelle (Gewerbesteuer) au-delà de l''abattement. À discuter avec le cabinet comptable.'),
('fr','set_tax_comm_share','Part commerciale au maximum (%)'),
('fr','set_tax_comm_abs','Chiffre d''affaires commercial au maximum (€)'),
('fr','set_tax_comm_hint','Les deux doivent être respectés, sinon l''ensemble des revenus est réputé commercial. En Allemagne, 3 % du chiffre d''affaires hors taxes et 24 500 € par an, d''après la jurisprudence relative au § 15 Abs. 3 Nr. 1 EStG.'),
('fr','help_est_title','Impôt sur le revenu : qui paie quoi'),
('fr','help_est_who','Le groupe lui-même ne paie pas d''impôt sur le revenu. Son bénéfice est déterminé une fois puis réparti entre les membres — l''administration fiscale appelle cela une constatation séparée et unifiée (gesonderte und einheitliche Feststellung). Chaque membre déclare sa part dans sa propre déclaration. Il faut donc les deux : des chiffres propres pour le groupe et la clarté sur ce qui revient à chacun.'),
('fr','help_est_euer','Pour un groupe, le bénéfice est en règle générale déterminé par une comptabilité de caisse (Einnahmen-Überschuss-Rechnung, EÜR) : encaissé moins décaissé, dans l''année du paiement. C''est exactement ce qu''est un livre de caisse — tenu proprement, le travail est pour l''essentiel fait.'),
('fr','help_est_merch','Jouer est une activité artistique, vendre des T-shirts est du commerce. Dans une société de personnes, une petite part commerciale suffit pour que l''ensemble des revenus soit réputé commercial — y compris ceux des concerts. Ce n''est toléré qu''en dessous des deux seuils à la fois : moins de trois pour cent du chiffre d''affaires hors taxes et moins de 24 500 € par an. Trois pour cent, c''est peu : avec 20 000 € de cachets, on peut vendre pour environ 600 € de merch. Au-delà, c''est tout le groupe qui devient une entreprise commerciale, avec la taxe professionnelle (Gewerbesteuer) au-delà de l''abattement de 24 500 €.'),
('fr','help_est_hobby','Et le cas inverse : qui ne fait aucun bénéfice pendant des années et n''en vise aucun peut être classé par le fisc comme activité d''agrément (Liebhaberei). Le groupe n''est alors pas une entreprise au sens fiscal — et les pertes ne valent rien non plus.'),
('fr','help_est_src_est15','— quand l''ensemble des revenus devient commercial'),
('fr','help_est_src_est18','— l''activité artistique'),
('fr','help_est_src_bfh','— le seuil de minimis issu de la jurisprudence'),
('fr','help_est_own_title','Ce qui compte chez le musicien individuel'),
('fr','help_est_own_taxed','Ce qui est imposé, c''est la part de bénéfice — même si rien n''a été versé. Si le groupe met de l''argent de côté pour une sono, personne n''a vu d''argent et chacun déclare pourtant sa part. Cela surprend régulièrement.'),
('fr','help_est_own_costs','En face, il y a ce qui n''apparaît pas du tout dans les chiffres du groupe : son propre instrument avec cordes et accessoires, les trajets vers les répétitions et les concerts, les partitions et la littérature spécialisée, un bureau à domicile sous des conditions strictes, les cotisations à la caisse sociale des artistes (Künstlersozialkasse). Cela va dans la déclaration personnelle.'),
('fr','help_est_own_km','Les trajets en voiture personnelle pour le groupe sont des déplacements professionnels : 30 centimes par kilomètre parcouru. À ne pas confondre avec le forfait domicile-travail (Pendlerpauschale), qui passe à 38 centimes en 2026 — il vise le trajet vers un lieu de travail fixe, et qui joue chaque fois ailleurs n''en a pas.'),
('fr','help_est_own_home','Pour le travail à domicile, 6 euros par jour, au maximum 1 260 euros par an — cela correspond à 210 jours.'),
('fr','help_est_own_ksk','La caisse sociale des artistes (Künstlersozialkasse) assure celui qui exerce une activité artistique, indépendante et lucrative. En dessous de 3 900 euros de revenu annuel, aucune obligation d''assurance n''est constatée. À l''inverse : si le groupe paie lui-même des musiciens invités, il peut devoir la contribution sociale des artistes (Künstlersozialabgabe) — 4,9 pour cent en 2026, avec un seuil de minimis de 1 000 euros par an.'),
('fr','help_est_src_ksk','— qui est assuré et à partir de quand'),
('fr','fl_file_sealed','Ce fichier est stocké chiffré et ne peut pas être ouvert avec la clé enregistrée.'),
('fr','set_crypt','Chiffrement des données au repos'),
('fr','set_crypt_on','Activé : les sauvegardes et les pièces jointes sont chiffrées.'),
('fr','set_crypt_off','Désactivé : les sauvegardes et les pièces jointes sont en clair.'),
('fr','set_crypt_scope','Sont chiffrées les sauvegardes et les pièces jointes sur le disque. Ne l''est pas la base de données en fonctionnement — le serveur doit pouvoir y calculer et y trier — ni les images sous /uploads, que le serveur web délivre directement.'),
('fr','set_crypt_test','Efficacité vérifiée : %s.'),
('fr','set_crypt_plain_files','%d pièces jointes datent d''avant et sont encore en clair.'),
('fr','set_crypt_seal_now','Les chiffrer maintenant'),
('fr','set_crypt_files_done','Toutes les pièces jointes sont chiffrées.'),
('fr','set_crypt_how','Générer une clé et l''inscrire comme « data_key » dans app/config.php :'),
('fr','set_crypt_lost','Conservez cette clé comme le mot de passe de la base de données — et pas dans la même sauvegarde. Sans elle, aucune sauvegarde chiffrée ne peut plus être ouverte.'),
('fr','set_crypt_law','L''art. 32 du RGPD (DSGVO) exige des mesures conformes à l''état de l''art et cite explicitement le chiffrement ; le point d exige en outre d''en tester régulièrement l''efficacité. C''est exactement ce que fait la ligne ci-dessus : sceller, rouvrir, et vérifier si une modification est repérée.'),
('fr','sys_crypt_off','aucune clé enregistrée'),
('fr','sys_crypt_off_hint','Les sauvegardes et les pièces jointes sont en clair. Qui met la main sur la sauvegarde — sur le NAS, sur la cible FTP, dans le cloud — lit la caisse au passage. Générer une clé : php app/backup.php key'),
('fr','sys_crypt_broken','Le chiffrement est activé, mais la vérification échoue. Tant que ce n''est pas éclairci, on ne peut pas compter sur les sauvegardes.'),
('fr','sys_webstat','Statistiques de visite'),
('fr','sys_webstat_open','lisibles publiquement'),
('fr','sys_webstat_closed','protégées'),
('fr','sys_webstat_unknown','non vérifiable'),
('fr','sys_webstat_hint','Sous /plesk-stat se trouvent les rapports AWStats de ce domaine, et ils contiennent les adresses IP de vos visiteurs — ouverts à quiconque connaît l''adresse. Dans Plesk, sous « Sites Web & domaines → Hébergement et DNS → Statistiques Web », cochez « Accessible via un répertoire protégé par mot de passe ».'),
('fr','sys_crypt_files','Pièces jointes chiffrées'),
('fr','sys_crypt_files_hint','Les chiffrer après coup dans les réglages, sous « Chiffrement des données au repos ».'),
('fr','fl_crypt_no_key','Aucune clé n''est enregistrée.'),
('fr','fl_crypt_sealed','%d pièces jointes chiffrées.'),
('fr','fl_crypt_sealed_some','%d pièces jointes chiffrées, %d en échec — détails dans le journal des erreurs.'),
('es','up_title','Actualización'),
('es','up_available','La versión %s ya está'),
('es','up_intro','Bandregie no se actualiza sola. Para eso el servidor web tendría que poder escribir en su propio directorio, y entonces cualquier agujero que permita escribir un archivo una sola vez se convierte en una toma de control permanente. Un comando en la consola cuesta dos segundos más y no ese precio.'),
('es','up_installed','Instalada:'),
('es','up_how_git','El script primero guarda la base de datos y los archivos y después descarga la nueva versión:'),
('es','up_how_plesk','Esta instalación funciona con Plesk: el directorio que se sirve no es una copia de trabajo de Git, un «git pull» no haría nada aquí. Plesk descarga y despliega:'),
('es','up_manual','Esta instalación no es una copia de trabajo de Git. Copia los archivos nuevos, pero sin sobrescribir nunca data/ ni app/config.php, y haz antes una copia de seguridad.'),
('es','up_cron','Si quieres que funcione solo, la línea va en el crontab del usuario propietario de la copia de trabajo:'),
('es','up_check','Comprobar una vez al día si hay una versión nueva'),
('es','up_check_hint','Le pregunta a GitHub el número de versión, sin identificarse y sin datos sobre esta instalación. Apagado, Bandregie nunca sale a la red por su cuenta.'),
('es','fl_up_saved','Ajuste de actualización guardado.'),
('es','tax_title','El límite de facturación a la vista'),
('es','tax_turnover_year','Facturación %d:'),
('es','tax_of','de'),
('es','tax_state_close','Os estáis acercando al límite del año en curso. De ahí salen dos cosas: la exención termina el 1 de enero de todos modos, porque este año ya está por encima del límite del año anterior, y si además superáis el límite superior, termina de inmediato, con la propia facturación que lo supera.'),
('es','tax_state_next_year','La facturación está por encima del límite del año anterior. Para este año eso no cambia nada, pero la exención termina sola el 1 de enero, sin importar cómo vaya el año siguiente. A partir de ahí, el IVA va en cada factura.'),
('es','tax_state_over_this','Se ha superado el límite del año en curso. Con eso termina la exención: habladlo con vuestra asesoría antes de que salga la siguiente factura.'),
('es','tax_state_over_prev','La facturación del año pasado estuvo por encima del límite. Por eso la exención ya no vale para este año.'),
('es','tax_counts_hint','Se cuentan todos los ingresos del grupo salvo las aportaciones de los miembros: son contribuciones, no ventas. Los apuntes privados quedan fuera.'),
('es','tax_gbr_hint','Se calcula con la facturación del grupo en conjunto. Eso encaja si tocáis y facturáis juntos, que es lo habitual. Si cada miembro emite sus propias facturas, entonces cuenta cada uno por su cuenta y esta cifra no dice nada al respecto.'),
('es','tax_no_advice','Una ayuda de cálculo, no un asesoramiento fiscal, y nada de esto es jurídicamente vinculante. De lo que al final se declara responden el grupo y su asesoría, no este programa. Los límites están en los ajustes y se pueden cambiar.'),
('es','set_tax','Valores fiscales'),
('es','set_tax_hint','Los valores predeterminados son los alemanes. Si el legislador cambia las cifras, o si estáis en otro país, ponedlas aquí y confirmad la fecha.'),
('es','set_tax_small','Usamos el régimen de pequeñas empresas (Kleinunternehmerregelung, § 19 UStG)'),
('es','set_tax_small_hint','Solo así la caja lleva la cuenta y avisa al llegar al límite.'),
('es','set_tax_prev','Límite año anterior (€)'),
('es','set_tax_gwg','Límite de bienes de escaso valor (GWG, € neto)'),
('es','set_tax_gwg_hint','Hasta este importe un aparato se amortiza en el año de la compra; por encima, a lo largo de su vida útil.'),
('es','set_tax_checked','Valores comprobados por última vez el'),
('es','set_tax_source','Situación en julio de 2026, Alemania: § 19 UStG 25.000 € año anterior y 100.000 € año en curso, § 6 Abs. 2 EStG 800 € netos.'),
('es','sys_tax_stale','Valores fiscales'),
('es','sys_tax_stale_detail','sin confirmar desde hace más de un año'),
('es','sys_tax_stale_conseq','Comprobad si los límites siguen siendo correctos y confirmad la fecha en los ajustes.'),
('es','fl_tax_saved','Valores fiscales guardados.'),
('es','help_tax_title','Límite de facturación y régimen de pequeñas empresas (Kleinunternehmerregelung)'),
('es','help_tax_what','Quien usa el régimen de pequeñas empresas (Kleinunternehmerregelung, § 19 UStG) no indica IVA en las facturas ni lo ingresa. Eso vale mientras la facturación del año anterior quede por debajo de un límite y la del año en curso por debajo del otro. Las dos cifras están en los ajustes y se pueden cambiar.'),
('es','help_tax_band','Se calcula con la facturación del grupo en conjunto, no por cabeza. En cuanto varias personas tocan juntas y se reparten un caché, forman jurídicamente una sociedad civil (GbR): no hace falta inscribirla, nace del propio hecho. A efectos del IVA, esa GbR es el sujeto pasivo, así que el límite vale una sola vez para todos. Si en cambio cada miembro emite sus propias facturas, cada uno tiene su propio límite y la cifra de la caja no dice nada al respecto.'),
('es','help_tax_counts','Cuentan como facturación los cachés, el merch y el equipo vendido. Las aportaciones de los miembros no cuentan: son contribuciones, no ventas. Los apuntes privados quedan fuera de todos modos.'),
('es','help_tax_over','El límite del año en curso es un techo duro: ya la propia facturación con la que se supera está sujeta a impuesto. Por eso la caja avisa a partir de cuatro quintos del límite, y no cuando ya es tarde. Quien pierde el régimen tributa los conciertos al tipo reducido y el merch al tipo pleno; lo que eso significa para vosotros es mejor aclararlo antes que después.'),
('es','help_tax_next_year','El caso más probable es el más silencioso: si la facturación se queda entre los dos límites, este año no cambia nada, pero la exención termina el 1 de enero del año siguiente, de forma automática y sin aviso. Cuánto se facture en el año nuevo ya no importa. Quien se entera solo al recibir la liquidación lleva un año emitiendo facturas sin IVA que ahora tiene que regularizar.'),
('es','help_tax_gwg','Para los aparatos hay un segundo límite: hasta este importe neto una compra se amortiza en el año de la adquisición; por encima, se reparte a lo largo de la vida útil. Para altavoces la tabla oficial (AfA-Tabelle) fija siete años, y para equipos de sonido completos, nueve.'),
('es','help_tax_sources','De dónde salen las cifras'),
('es','help_tax_checked','Comprobado por última vez el %s. Las páginas de consejos suelen ir por detrás; los textos legales son la fuente fiable.'),
('es','help_tax_src_ustg','— los límites de facturación del régimen de pequeñas empresas'),
('es','help_tax_src_estg','— el límite de los bienes de escaso valor'),
('es','help_tax_src_afa','— la vida útil para todo lo que esté por encima'),
('es','help_tax_offset_title','Lo que se compensa entre sí'),
('es','help_tax_offset_intro','La caja suma lo que se ha apuntado. Algunas cosas parecen ahí un ingreso o un gasto y fiscalmente son otra cosa: quien lo lee tal cual llega con la conciencia tranquila a una cifra equivocada.'),
('es','help_tax_offset_deposit','Una aportación es dinero que entra para el grupo y dinero que sale para el miembro. Es una contribución, no una venta, y por eso no cuenta como facturación.'),
('es','help_tax_offset_payout','Un reparto figura en el libro como gasto, pero para una GbR no es un gasto de explotación: distribuye un beneficio que ya se ha generado. Quien lo resta del beneficio lo está descontando dos veces.'),
('es','help_tax_offset_private','Lo que un miembro ha pagado de su bolsillo es su gasto y no el del grupo. Por eso esos apuntes quedan fuera; en la declaración del propio miembro sí pueden contar.'),
('es','help_tax_offset_gwg','Un aparato por encima del límite de valor sale de la caja en un solo importe, pero reduce el beneficio repartido a lo largo de su vida útil. En el libro de caja hay un año; fiscalmente son varios.'),
('es','help_tax_levels','Lo que reduce impuestos actúa en dos niveles: algunas cosas bajan lo que ha ganado el grupo y otras bajan lo que declara cada miembro. El instrumento propio, el viaje al ensayo, la parte del beneficio: eso va en la declaración personal y no en las cifras del grupo. Quien lo mezcla todo obtiene una suma que no es correcta para ninguno de los dos lados.'),
('es','tax_comm_title','Parte comercial'),
('es','tax_comm_intro','Tocar es artístico, vender merch es comercio. En una sociedad de personas basta una pequeña parte comercial para que todos los ingresos pasen a ser empresariales, también los de los conciertos. Solo se tolera por debajo de los dos límites.'),
('es','tax_comm_of','de'),
('es','tax_comm_state_close','La parte comercial se acerca al límite.'),
('es','tax_comm_state_over','La parte comercial está por encima del límite. Con eso todos los ingresos del grupo se consideran empresariales, también los de los conciertos, con el impuesto de actividades económicas (Gewerbesteuer) por encima del mínimo exento. Esto hay que hablarlo con la asesoría.'),
('es','set_tax_comm_share','Parte comercial como máximo (%)'),
('es','set_tax_comm_abs','Facturación comercial como máximo (€)'),
('es','set_tax_comm_hint','Se tienen que cumplir las dos cosas; si no, todos los ingresos se consideran empresariales. En Alemania, el 3 % de la facturación neta y 24.500 € al año, según la jurisprudencia sobre el § 15 Abs. 3 Nr. 1 EStG.'),
('es','help_est_title','Impuesto sobre la renta: quién paga qué'),
('es','help_est_who','El grupo en sí no paga impuesto sobre la renta. Su beneficio se determina una vez y se reparte entre los miembros; en Hacienda eso se llama determinación separada y unitaria (gesonderte und einheitliche Feststellung). Cada miembro declara su parte en su propia declaración. Por eso hacen falta las dos cosas: cifras limpias para el grupo y claridad sobre qué le toca a cada uno.'),
('es','help_est_euer','En una banda el beneficio se determina por lo general con una cuenta de ingresos y gastos de caja (Einnahmen-Überschuss-Rechnung, EÜR): lo cobrado menos lo pagado, en el año del pago. Eso es justamente un libro de caja: bien llevado, el trabajo está hecho en lo esencial.'),
('es','help_est_merch','Tocar es una actividad artística, vender camisetas es comercio. En una sociedad de personas basta una pequeña parte comercial para que todos los ingresos se consideren empresariales, también los de los conciertos. Solo se tolera por debajo de los dos límites a la vez: menos del tres por ciento de la facturación neta y menos de 24.500 € al año. El tres por ciento es poco: con 20.000 € de cachés se pueden vender unos 600 € de merch. Por encima, todo el grupo pasa a ser una actividad empresarial, con Gewerbesteuer por encima del mínimo exento de 24.500 €.'),
('es','help_est_hobby','Y el caso contrario: quien durante años no obtiene beneficio ni lo pretende puede pasar para Hacienda por afición (Liebhaberei). Entonces el grupo no es fiscalmente una actividad, y las pérdidas tampoco valen nada.'),
('es','help_est_src_est15','— cuándo todos los ingresos pasan a ser empresariales'),
('es','help_est_src_est18','— la actividad artística'),
('es','help_est_src_bfh','— el límite de minimis de la jurisprudencia'),
('es','help_est_own_title','Qué cuenta para cada músico'),
('es','help_est_own_taxed','Se tributa por la parte del beneficio, aunque no se haya repartido nada. Si el grupo ahorra para un equipo de PA, nadie ha visto dinero y aun así cada uno declara su parte. Eso sorprende una y otra vez.'),
('es','help_est_own_costs','Frente a eso está lo que no aparece en absoluto en las cifras del grupo: el instrumento propio con cuerdas y accesorios, los viajes a ensayos y conciertos, partituras y literatura especializada, un despacho en casa bajo condiciones estrictas, las cuotas a la caja social de artistas (Künstlersozialkasse). Eso va en la declaración personal.'),
('es','help_est_own_km','Los viajes con el coche propio para el grupo son desplazamientos de la actividad: 30 céntimos por kilómetro recorrido. No hay que confundirlo con la deducción por desplazamiento al trabajo (Pendlerpauschale), que en 2026 sube a 38 céntimos: esa vale para el trayecto a un centro de trabajo fijo, y no lo tiene quien toca cada vez en otro sitio.'),
('es','help_est_own_home','Por trabajar en casa hay 6 euros al día, como máximo 1.260 euros al año, lo que corresponde a 210 días.'),
('es','help_est_own_ksk','La caja social de artistas (Künstlersozialkasse) asegura a quien trabaja de forma artística, autónoma y con ánimo de lucro. Por debajo de 3.900 euros de ingresos anuales no se declara obligación de aseguramiento. Al revés: si el grupo paga a músicos invitados, puede deber la Künstlersozialabgabe, un 4,9 por ciento en 2026, con un límite de minimis de 1.000 euros al año.'),
('es','help_est_src_ksk','— quién está asegurado y desde cuándo'),
('es','fl_file_sealed','Este archivo está guardado cifrado y no se puede abrir con la clave registrada.'),
('es','set_crypt','Cifrado de los datos en reposo'),
('es','set_crypt_on','Activado: las copias de seguridad y los adjuntos están cifrados.'),
('es','set_crypt_off','Desactivado: las copias de seguridad y los adjuntos están en claro.'),
('es','set_crypt_scope','Están cifradas las copias de seguridad y los archivos adjuntos en el disco. No lo está la base de datos en marcha, porque ahí el servidor tiene que poder calcular y ordenar, ni las imágenes de /uploads, que el servidor web entrega directamente.'),
('es','set_crypt_test','Eficacia comprobada: %s.'),
('es','set_crypt_plain_files','%d adjuntos son de antes y siguen en claro.'),
('es','set_crypt_seal_now','Cifrarlos ahora'),
('es','set_crypt_files_done','Todos los adjuntos están cifrados.'),
('es','set_crypt_how','Genera una clave y ponla como «data_key» en app/config.php:'),
('es','set_crypt_lost','Guarda esta clave igual que la contraseña de la base de datos, y no en la misma copia de seguridad. Sin ella no se puede abrir ninguna copia cifrada.'),
('es','set_crypt_law','El art. 32 del RGPD (DSGVO) exige medidas acordes al estado de la técnica y menciona el cifrado de forma expresa; la letra d exige además comprobar su eficacia con regularidad. Eso es justo lo que hace la línea de arriba: sellar, volver a abrir y comprobar si se detecta una alteración.'),
('es','sys_crypt_off','ninguna clave registrada'),
('es','sys_crypt_off_hint','Las copias de seguridad y los adjuntos están en claro. Quien se hace con la copia, en el NAS, en el destino FTP o en la nube, lee también la caja. Generar una clave: php app/backup.php key'),
('es','sys_crypt_broken','El cifrado está activado, pero la comprobación falla. Hasta que se aclare, no hay que fiarse de las copias de seguridad.'),
('es','sys_webstat','Estadísticas de visitas'),
('es','sys_webstat_open','legibles públicamente'),
('es','sys_webstat_closed','protegidas'),
('es','sys_webstat_unknown','no comprobable'),
('es','sys_webstat_hint','En /plesk-stat están los informes de AWStats de este dominio, y ahí figuran las direcciones IP de vuestros visitantes, abiertas a cualquiera que conozca la dirección. En Plesk, en «Sitios web y dominios → Hosting y DNS → Estadísticas web», marca «Acceso a través de un directorio protegido con contraseña».'),
('es','sys_crypt_files','Adjuntos cifrados'),
('es','sys_crypt_files_hint','Cifrarlos después en los ajustes, en «Cifrado de los datos en reposo».'),
('es','fl_crypt_no_key','No hay ninguna clave registrada.'),
('es','fl_crypt_sealed','%d adjuntos cifrados.'),
('es','fl_crypt_sealed_some','%d adjuntos cifrados, %d fallidos — detalles en el registro de errores.'),
('it','up_title','Aggiornamento'),
('it','up_available','La versione %s è disponibile'),
('it','up_intro','Bandregie non si aggiorna da sé. Per farlo il server web dovrebbe poter scrivere nella propria directory, e allora ogni falla che permette di scrivere un file una volta diventa un controllo permanente. Un comando da console costa due secondi in più e non quel prezzo.'),
('it','up_installed','Installata:'),
('it','up_how_git','Lo script salva prima database e file e poi scarica la nuova versione:'),
('it','up_how_plesk','Questa installazione gira sotto Plesk: la directory servita non è una copia di lavoro Git, un «git pull» qui non farebbe nulla. Plesk scarica e distribuisce:'),
('it','up_manual','Questa installazione non è una copia di lavoro Git. Copia i file nuovi, ma senza mai sovrascrivere data/ e app/config.php, e prima fai un backup.'),
('it','up_cron','Se deve funzionare da solo, va nel crontab dell''utente proprietario della copia di lavoro:'),
('it','up_check','Controllare una volta al giorno se c''è una versione nuova'),
('it','up_check_hint','Chiede a GitHub il numero di versione, senza autenticazione e senza dati su questa installazione. Spento, Bandregie non contatta mai l''esterno di propria iniziativa.'),
('it','fl_up_saved','Impostazione di aggiornamento salvata.'),
('it','tax_title','La soglia di fatturato sotto controllo'),
('it','tax_turnover_year','Fatturato %d:'),
('it','tax_of','su'),
('it','tax_state_close','Vi state avvicinando alla soglia dell''anno in corso. Ne derivano due cose: l''esenzione finisce comunque il 1° gennaio, perché quest''anno è già sopra la soglia dell''anno precedente, e se superate anche la soglia superiore finisce subito, con il fatturato stesso che la supera.'),
('it','tax_state_next_year','Il fatturato supera la soglia dell''anno precedente. Per quest''anno non cambia nulla, ma l''esenzione finisce da sola il 1° gennaio, a prescindere da come andrà l''anno prossimo. Da quel momento l''IVA va su ogni fattura.'),
('it','tax_state_over_this','La soglia dell''anno in corso è stata superata. L''esenzione finisce qui: parlatene con il vostro commercialista prima che parta la prossima fattura.'),
('it','tax_state_over_prev','Il fatturato dell''anno scorso era sopra la soglia. Per quest''anno l''esenzione non vale più.'),
('it','tax_counts_hint','Si contano tutte le entrate della band tranne i versamenti dei membri: sono contributi, non vendite. Le registrazioni private restano fuori.'),
('it','tax_gbr_hint','Il calcolo usa il fatturato della band nel suo insieme. Va bene se suonate e fatturate insieme, il caso normale. Se ogni membro emette fatture proprie, conta invece ciascuno per sé, e questo numero non dice nulla in proposito.'),
('it','tax_no_advice','Un aiuto al calcolo, non una consulenza fiscale, e niente di tutto questo è giuridicamente vincolante. Di quello che alla fine viene dichiarato rispondono la band e il suo commercialista, non questo programma. Le soglie sono nelle impostazioni e si possono cambiare.'),
('it','set_tax','Valori fiscali'),
('it','set_tax_hint','I valori predefiniti sono quelli tedeschi. Se il legislatore cambia i numeri, o se siete altrove, inseriteli qui e confermate la data.'),
('it','set_tax_small','Usiamo il regime per piccole imprese (Kleinunternehmerregelung, § 19 UStG)'),
('it','set_tax_small_hint','Solo così la cassa tiene il conto e avvisa alla soglia.'),
('it','set_tax_prev','Soglia anno precedente (€)'),
('it','set_tax_gwg','Soglia beni di modico valore (GWG, € netto)'),
('it','set_tax_gwg_hint','Fino a questo importo un apparecchio si ammortizza nell''anno dell''acquisto, oltre si distribuisce sulla vita utile.'),
('it','set_tax_checked','Valori verificati l''ultima volta il'),
('it','set_tax_source','Situazione a luglio 2026, Germania: § 19 UStG 25.000 € anno precedente e 100.000 € anno in corso, § 6 Abs. 2 EStG 800 € netti.'),
('it','sys_tax_stale','Valori fiscali'),
('it','sys_tax_stale_detail','non confermati da più di un anno'),
('it','sys_tax_stale_conseq','Verificate se le soglie sono ancora giuste e confermate la data nelle impostazioni.'),
('it','fl_tax_saved','Valori fiscali salvati.'),
('it','help_tax_title','Soglia di fatturato e regime per piccole imprese (Kleinunternehmerregelung)'),
('it','help_tax_what','Chi usa il regime per piccole imprese (Kleinunternehmerregelung, § 19 UStG) non espone IVA in fattura e non la versa. Vale finché il fatturato dell''anno precedente resta sotto una soglia e quello dell''anno in corso sotto l''altra. Entrambi i numeri sono nelle impostazioni e si possono cambiare.'),
('it','help_tax_band','Il calcolo usa il fatturato della band nel suo insieme, non pro capite. Appena più persone suonano insieme e dividono un cachet, sono giuridicamente una società semplice (GbR): non serve alcuna iscrizione, nasce dal fatto stesso. Ai fini IVA questa GbR è il soggetto passivo, quindi la soglia vale una sola volta per tutti. Se invece ogni membro emette fatture proprie, ciascuno ha la sua soglia, e il numero in cassa non dice nulla in proposito.'),
('it','help_tax_counts','Contano come fatturato i cachet, il merch e l''attrezzatura venduta. I versamenti dei membri no: sono contributi, non vendite. Le registrazioni private restano comunque fuori.'),
('it','help_tax_over','La soglia dell''anno in corso è un tetto rigido: è già imponibile il fatturato stesso con cui viene superata. Per questo la cassa si fa sentire a partire da quattro quinti della soglia, non quando ormai è tardi. Chi perde il regime tassa i concerti con aliquota ridotta e il merch con quella piena; che cosa significhi per voi è meglio chiarirlo prima che dopo.'),
('it','help_tax_next_year','Il caso più probabile è quello più silenzioso: se il fatturato resta tra le due soglie, quest''anno non cambia nulla, ma l''esenzione finisce il 1° gennaio dell''anno successivo, in automatico e senza comunicazione. Quanto sarà il fatturato del nuovo anno non conta più. Chi lo scopre solo con l''avviso di accertamento ha scritto per un anno fatture senza IVA che deve regolarizzare.'),
('it','help_tax_gwg','Per gli apparecchi vale una seconda soglia: fino a questo importo netto un acquisto si ammortizza nell''anno dell''acquisizione, oltre si distribuisce sulla vita utile. Per i diffusori la tabella ufficiale (AfA-Tabelle) prevede sette anni, per interi impianti di amplificazione nove.'),
('it','help_tax_sources','Da dove vengono i numeri'),
('it','help_tax_checked','Ultima verifica il %s. I siti di consulenza qui sono spesso in ritardo: i testi di legge sono la fonte affidabile.'),
('it','help_tax_src_ustg','— le soglie di fatturato del regime per piccole imprese'),
('it','help_tax_src_estg','— la soglia dei beni di modico valore'),
('it','help_tax_src_afa','— la vita utile per tutto ciò che sta sopra'),
('it','help_tax_offset_title','Che cosa si annulla a vicenda'),
('it','help_tax_offset_intro','La cassa somma quello che è stato registrato. Alcune voci sembrano entrate o uscite e fiscalmente sono altro: chi le legge alla lettera arriva in buona fede a un numero sbagliato.'),
('it','help_tax_offset_deposit','Un versamento è denaro in entrata per la band e in uscita per il membro. È un contributo, non una vendita, e perciò non conta nel fatturato.'),
('it','help_tax_offset_payout','Una distribuzione compare a libro come uscita, ma per una GbR non è un costo d''esercizio: ripartisce un utile già maturato. Chi la scala dall''utile lo sottrae due volte.'),
('it','help_tax_offset_private','Quello che un membro ha pagato di tasca propria è una sua spesa, non della band. Perciò quelle registrazioni restano fuori: nella dichiarazione del membro stesso possono benissimo contare.'),
('it','help_tax_offset_gwg','Un apparecchio sopra la soglia di valore esce dalla cassa in un''unica somma, ma riduce l''utile distribuito sulla vita utile. Nel libro cassa c''è un anno, fiscalmente sono più di uno.'),
('it','help_tax_levels','Ci sono due livelli su cui si riducono le imposte: alcune cose abbassano quello che ha guadagnato la band, altre abbassano quello che dichiara il singolo membro. Lo strumento personale, il viaggio verso le prove, la quota di utile: vanno nella dichiarazione personale e non nei numeri della band. Chi mette tutto insieme ottiene una somma che non è giusta per nessuna delle due parti.'),
('it','tax_comm_title','Quota commerciale'),
('it','tax_comm_intro','Suonare è attività artistica, vendere merch è commercio. In una società di persone basta una piccola quota commerciale perché tutti i redditi diventino d''impresa, anche quelli dei concerti. È tollerato solo sotto entrambe le soglie.'),
('it','tax_comm_of','su'),
('it','tax_comm_state_close','La quota commerciale si avvicina alla soglia.'),
('it','tax_comm_state_over','La quota commerciale supera la soglia. Con ciò tutti i redditi della band valgono come redditi d''impresa, anche quelli dei concerti, con l''imposta sulle attività produttive (Gewerbesteuer) oltre la franchigia. Da discutere con il commercialista.'),
('it','set_tax_comm_share','Quota commerciale al massimo (%)'),
('it','set_tax_comm_abs','Fatturato commerciale al massimo (€)'),
('it','set_tax_comm_hint','Devono valere entrambe, altrimenti tutti i redditi sono considerati d''impresa. In Germania il 3 % del fatturato netto e 24.500 € l''anno, dalla giurisprudenza sul § 15 Abs. 3 Nr. 1 EStG.'),
('it','help_est_title','Imposta sul reddito: chi paga che cosa'),
('it','help_est_who','La band in sé non paga imposta sul reddito. L''utile viene determinato una volta e ripartito tra i membri: all''ufficio delle imposte si chiama accertamento separato e unitario (gesonderte und einheitliche Feststellung). Ogni membro indica la sua quota nella propria dichiarazione. Per questo servono entrambe le cose: numeri puliti per la band e chiarezza su quanto arriva al singolo.'),
('it','help_est_euer','In una band l''utile si determina di regola con un conto di cassa (Einnahmen-Überschuss-Rechnung, EÜR): incassato meno pagato, nell''anno del pagamento. È esattamente quello che è un libro cassa: tenuto bene, il lavoro è sostanzialmente fatto.'),
('it','help_est_merch','Suonare è un''attività artistica, vendere magliette è commercio. In una società di persone basta una piccola quota commerciale perché tutti i redditi valgano come redditi d''impresa, anche quelli dei concerti. È tollerato solo sotto entrambe le soglie insieme: sotto il tre per cento del fatturato netto e sotto 24.500 € l''anno. Il tre per cento è poco: con 20.000 € di cachet si può vendere merch per circa 600 €. Oltre, tutta la band diventa un''impresa, con Gewerbesteuer oltre la franchigia di 24.500 €.'),
('it','help_est_hobby','E il caso opposto: chi per anni non fa utili e nemmeno li persegue può risultare al fisco un''attività per diletto (Liebhaberei). Allora la band fiscalmente non è un''impresa, e anche le perdite non valgono nulla.'),
('it','help_est_src_est15','— quando tutti i redditi diventano d''impresa'),
('it','help_est_src_est18','— l''attività artistica'),
('it','help_est_src_bfh','— la soglia di minimis dalla giurisprudenza'),
('it','help_est_own_title','Che cosa conta per il singolo musicista'),
('it','help_est_own_taxed','Si tassa la quota di utile, anche se non è stato distribuito nulla. Se la band mette da parte per un impianto, nessuno ha visto soldi e ciascuno dichiara comunque la sua quota. È una cosa che sorprende regolarmente.'),
('it','help_est_own_costs','Di contro c''è quello che nei numeri della band non compare affatto: lo strumento personale con corde e accessori, i viaggi verso prove e concerti, spartiti e letteratura specialistica, uno studio in casa a condizioni ristrette, i contributi alla cassa sociale degli artisti (Künstlersozialkasse). Va nella dichiarazione personale.'),
('it','help_est_own_km','I viaggi con l''auto personale per la band sono trasferte di lavoro: 30 centesimi per chilometro percorso. Da non confondere con la detrazione per il tragitto casa-lavoro (Pendlerpauschale), che nel 2026 sale a 38 centesimi: vale per il percorso verso una sede di lavoro fissa, e non ce l''ha chi ogni volta suona altrove.'),
('it','help_est_own_home','Per il lavoro da casa ci sono 6 euro al giorno, al massimo 1.260 euro l''anno, che corrispondono a 210 giorni.'),
('it','help_est_own_ksk','La cassa sociale degli artisti (Künstlersozialkasse) assicura chi svolge un''attività artistica in proprio e a scopo di lucro. Sotto 3.900 euro di reddito annuo non viene accertato alcun obbligo assicurativo. Al contrario: se la band paga musicisti ospiti, può dovere il contributo Künstlersozialabgabe, il 4,9 per cento nel 2026, con una soglia di minimis di 1.000 euro l''anno.'),
('it','help_est_src_ksk','— chi è assicurato e da quando'),
('it','fl_file_sealed','Questo file è archiviato cifrato e non si apre con la chiave inserita.'),
('it','set_crypt','Cifratura dei dati a riposo'),
('it','set_crypt_on','Attivo: backup e allegati sono cifrati.'),
('it','set_crypt_off','Spento: backup e allegati sono in chiaro.'),
('it','set_crypt_scope','Sono cifrati i backup e gli allegati su disco. Non lo è il database in funzione, perché lì il server deve poter calcolare e ordinare, e nemmeno le immagini sotto /uploads, che il server web consegna direttamente.'),
('it','set_crypt_test','Efficacia verificata: %s.'),
('it','set_crypt_plain_files','%d allegati risalgono a prima e sono ancora in chiaro.'),
('it','set_crypt_seal_now','Cifrali adesso'),
('it','set_crypt_files_done','Tutti gli allegati sono cifrati.'),
('it','set_crypt_how','Genera una chiave e inseriscila come «data_key» in app/config.php:'),
('it','set_crypt_lost','Conserva questa chiave come la password del database, e non nello stesso backup. Senza di essa nessun backup cifrato si può più aprire.'),
('it','set_crypt_law','L''art. 32 GDPR (DSGVO) richiede misure allo stato dell''arte e nomina esplicitamente la cifratura; la lettera d richiede inoltre di verificarne regolarmente l''efficacia. È esattamente quello che fa la riga qui sopra: sigillare, riaprire e controllare se una modifica viene notata.'),
('it','sys_crypt_off','nessuna chiave inserita'),
('it','sys_crypt_off_hint','Backup e allegati sono in chiaro. Chi mette le mani sul backup, sul NAS, sulla destinazione FTP o nel cloud, legge anche la cassa. Generare una chiave: php app/backup.php key'),
('it','sys_crypt_broken','La cifratura è attiva, ma la verifica fallisce. Finché non è chiarito, sui backup non si può contare.'),
('it','sys_webstat','Statistiche visitatori'),
('it','sys_webstat_open','leggibili pubblicamente'),
('it','sys_webstat_closed','protette'),
('it','sys_webstat_unknown','non verificabile'),
('it','sys_webstat_hint','Sotto /plesk-stat ci sono i rapporti AWStats di questo dominio, e dentro ci sono gli indirizzi IP dei vostri visitatori, aperti a chiunque conosca l''indirizzo. In Plesk, sotto «Siti web e domini → Hosting e DNS → Statistiche web», metti la spunta su «Accesso tramite directory protetta da password».'),
('it','sys_crypt_files','Allegati cifrati'),
('it','sys_crypt_files_hint','Cifrarli a posteriori nelle impostazioni, sotto «Cifratura dei dati a riposo».'),
('it','fl_crypt_no_key','Non è inserita nessuna chiave.'),
('it','fl_crypt_sealed','%d allegati cifrati.'),
('it','fl_crypt_sealed_some','%d allegati cifrati, %d falliti — dettagli nel registro degli errori.'),
